import { chromium } from 'playwright-core';
import fs from 'node:fs';
import path from 'node:path';

const EVIDENCE = process.env.EVIDENCE;
const ST_URL = process.env.ST_URL;
const report = {
  yellowmiSha: fs.readFileSync(path.join(EVIDENCE, 'yellowmi-sha.txt'), 'utf8').trim(),
  worldBackstageSha: fs.readFileSync(path.join(EVIDENCE, 'world-backstage-sha.txt'), 'utf8').trim(),
  sillyTavernSha: fs.readFileSync(path.join(EVIDENCE, 'sillytavern-sha.txt'), 'utf8').trim(),
  source: { character: 'SillyTavern 1.18.0 bundled default character: Seraphina', posts: 'generated by the configured real SillyTavern host model from the real current card', sim: 'World Backstage state produced only by the real chat/runtime if available' },
  stChat: {}, wechat: { status: 'unverified', checks: [] }, rednote: { status: 'unverified', checks: [] }, weibo: { status: 'unverified', checks: [] }, delivery: { status: 'unverified', checks: [] }, bridge: { status: 'unverified', checks: [] }, lifecycle: { status: 'unverified', checks: [] }, performance: { status: 'unverified', checks: [] }, physicalDevice: { status: 'blocked', reason: 'GitHub Actions runner has no physical Android device or system IME; browser emulation is not counted as physical-device evidence.' }, pageErrors: [], consoleErrors: [], networkFailures: [], blockers: []
};

fs.mkdirSync(EVIDENCE, { recursive: true });
const browser = await chromium.launch({ executablePath: process.env.CHROME_BIN, headless: true, args: ['--no-sandbox','--disable-dev-shm-usage'] });
const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
const page = await context.newPage();
page.setDefaultTimeout(5000);
page.on('pageerror', e => report.pageErrors.push(String(e?.stack || e)));
page.on('console', m => { if (m.type() === 'error') report.consoleErrors.push(m.text()); });
page.on('response', r => { if (r.status() >= 400) report.networkFailures.push({ status: r.status(), url: r.url() }); });

const note = (bucket, ok, text, extra={}) => bucket.checks.push({ ok, text, ...extra });
const statusFrom = bucket => bucket.status = bucket.checks.some(x => x.ok === false) ? 'failed' : bucket.checks.some(x => x.ok === true) ? 'passed' : bucket.status;
const sleep = ms => page.waitForTimeout(ms);

async function dismissHostPopups() {
  for (let i=0;i<8;i++) {
    const dialog = page.locator('dialog[open].popup').last();
    if (!await dialog.count()) return;
    const buttons = dialog.locator('button:visible');
    const labels = await buttons.allTextContents();
    let idx = labels.findIndex(x => /关闭|close|确定|ok|知道|got it|稍后|later|取消|cancel|继续|continue|跳过|skip/i.test(x));
    if (idx < 0 && labels.length) idx = labels.length - 1;
    if (idx >= 0) { try { await buttons.nth(idx).click(); await sleep(150); continue; } catch {} }
    await page.keyboard.press('Escape'); await sleep(120);
    if (await dialog.count()) break;
  }
}

async function hostState() {
  return page.evaluate(() => {
    const ctx = globalThis.SillyTavern?.getContext?.();
    const ch = ctx?.characters?.[ctx?.characterId];
    return { characterId: ctx?.characterId ?? null, character: ch?.name || '', chatId: ctx?.chatId || ctx?.getCurrentChatId?.() || '', chatLength: Array.isArray(ctx?.chat) ? ctx.chat.length : 0, isGenerating: Boolean(ctx?.isGenerating), hasGenerateRaw: typeof ctx?.generateRaw === 'function' };
  });
}

async function selectSeraphina() {
  const info = await page.evaluate(async () => {
    const t = await import('/script.js');
    const idx = (t.characters || []).findIndex(c => /seraphina/i.test(String(c?.name || '')));
    return { idx, names: (t.characters || []).map(c => c?.name || '') };
  });
  report.stChat.availableCharacters = info.names;
  if (info.idx < 0) throw new Error('Bundled Seraphina character was not loaded by real SillyTavern.');
  const drawer = page.locator('#right-nav-panel');
  if (!await drawer.isVisible().catch(()=>false)) await page.locator('#rightNavDrawerIcon').click().catch(()=>{});
  const byChid = page.locator(`#rm_print_characters_block .character_select[chid="${info.idx}"]`).first();
  const byText = page.locator('#rm_print_characters_block .character_select').filter({hasText:/Seraphina/i}).first();
  const target = await byChid.count() ? byChid : byText;
  await target.click({ timeout: 10000 });
  await page.waitForFunction(() => /seraphina/i.test(String(globalThis.SillyTavern?.getContext?.()?.characters?.[globalThis.SillyTavern?.getContext?.()?.characterId]?.name || '')), null, {timeout:15000});
  await sleep(500);
}

async function sendNarrative(text) {
  const before = await hostState();
  const input = page.locator('#send_textarea');
  await input.fill(text);
  await page.locator('#send_but').click();
  await page.waitForFunction(prev => {
    const ctx=globalThis.SillyTavern?.getContext?.();
    return Array.isArray(ctx?.chat) && ctx.chat.length >= prev + 2;
  }, before.chatLength, { timeout: 120000 });
  await page.waitForFunction(() => {
    const ctx=globalThis.SillyTavern?.getContext?.();
    return !ctx?.isGenerating;
  }, null, { timeout: 120000 }).catch(()=>{});
  await sleep(1000);
  return hostState();
}

async function openPhone() {
  await page.waitForSelector('#world-phone-launcher', {timeout:30000});
  await page.locator('#world-phone-launcher').click(); await sleep(250);
  const unlock = page.locator('#world-phone-stage [data-unlock]');
  if (await unlock.count()) { try { await unlock.click(); await sleep(200); } catch {} }
}
async function home() {
  for (let i=0;i<4;i++) {
    const back = page.locator('#world-phone-stage [data-app-back]').first();
    if (await back.count()) { await back.click().catch(()=>{}); await sleep(120); continue; }
    break;
  }
}
async function setMode(mode) {
  await home();
  await page.locator(`#world-phone-stage .wp-app[data-app="settings"]`).click(); await sleep(120);
  await page.locator(`#world-phone-stage [data-game-mode="${mode}"]`).click(); await sleep(180);
  const text = await page.locator('#world-phone-stage .wp-settings-app').innerText().catch(()=> '');
  await home();
  return text;
}
async function openApp(name) {
  await home();
  await page.locator(`#world-phone-stage .wp-app[data-app="${name}"]`).first().click(); await sleep(180);
}
async function gameState() {
  return page.evaluate(async () => {
    const m = await import('/scripts/extensions/third-party/echo-phone/src/phone-game.js?v=0.3.0-alpha.27');
    const s = m.readPhoneGameState(m.capturePhoneGameScope());
    return JSON.parse(JSON.stringify(s));
  });
}
async function waitGameIdle(timeout=120000) {
  await page.waitForFunction(async () => {
    const m = await import('/scripts/extensions/third-party/echo-phone/src/phone-game-ai.js?v=0.3.0-alpha.27');
    return !m.isPhoneGameGenerating();
  }, null, {timeout});
  await sleep(250);
}

try {
  await page.goto(ST_URL, { waitUntil:'domcontentloaded', timeout:60000 });
  await sleep(4500); await dismissHostPopups();
  await selectSeraphina();
  const selected = await hostState();
  report.stChat.selected = selected;
  if (!selected.hasGenerateRaw) throw new Error('Real SillyTavern context has no generateRaw.');
  const afterNarrative = await sendNarrative('用一句简短自然的话回应我：今天过得怎么样？');
  report.stChat.afterNarrative = afterNarrative;
  report.stChat.realNarrativeGeneration = afterNarrative.chatLength >= selected.chatLength + 2;
  await page.screenshot({ path:path.join(EVIDENCE,'01-real-seraphina-chat.png'), fullPage:true });

  await openPhone();
  const gameModeText = await setMode('game');
  report.stChat.gameModeSettingsText = gameModeText.slice(0,500);

  // P0 WeChat, real current card -> actor -> thread -> host model reply.
  await openApp('wechat');
  let s = await gameState();
  const actor = s.actors.find(a => /seraphina/i.test(a.name));
  note(report.wechat, Boolean(actor), 'real current SillyTavern card appears as a phone actor', { actor: actor?.name || null, actorId: actor?.id || null });
  const contactsTab = page.locator('#world-phone-stage [data-pg-view="relations"]').first();
  if (await contactsTab.count()) await contactsTab.click(); await sleep(100);
  const contact = page.locator('#world-phone-stage [data-pg-contact]').filter({hasText:/Seraphina/i}).first();
  note(report.wechat, await contact.count() > 0, 'Seraphina appears in the real contacts list');
  if (await contact.count()) {
    await contact.click(); await sleep(100);
    const detail = await page.locator('#world-phone-stage .echo-wx-contact-detail').innerText();
    note(report.wechat, /Seraphina/i.test(detail) && /熟悉度/.test(detail), 'contact detail binds name and relationship data from the current actor', { detail: detail.slice(0,700) });
    await page.locator('#world-phone-stage .echo-wx-contact-detail [data-pg-chat]').click(); await sleep(100);
  } else {
    await home(); await openApp('wechat');
    await page.locator('#world-phone-stage [data-pg-chat]').filter({hasText:/Seraphina/i}).first().click();
  }
  const msgText = `real-wechat-${Date.now()}`;
  await page.locator('#world-phone-stage [data-pg-message] [data-pg-draft]').fill(msgText);
  await page.locator('#world-phone-stage [data-pg-message]').evaluate(el => el.requestSubmit());
  await waitGameIdle();
  s = await gameState();
  const chatEvent = [...s.events].reverse().find(e => e.actorId === actor?.id && e.kind === 'chat' && e.text === msgText);
  note(report.wechat, Boolean(chatEvent), 'sent message is stored only on the selected real actor');
  note(report.wechat, chatEvent?.status === 'replied' && Boolean(chatEvent?.reply), 'real SillyTavern host model reply returned to the correct thread', { status: chatEvent?.status, reply: chatEvent?.reply?.slice(0,300) });
  const relAfterChat = actor ? s.relations[actor.id] : null;
  note(report.wechat, Boolean(relAfterChat), 'relationship state remains bound to the real actor after reply', { affinity: relAfterChat?.affinity, preferences: relAfterChat?.preferences, memory: relAfterChat?.memory?.slice(0,500) });
  await page.screenshot({ path:path.join(EVIDENCE,'02-wechat-real-thread.png') });
  statusFrom(report.wechat);

  // P1 RedNote generated by the real host model from the real card.
  await openApp('rednote');
  const rnRefresh = page.locator('#world-phone-stage [data-pg-refresh="rednote"]').first();
  if (await rnRefresh.count()) { await rnRefresh.click(); await waitGameIdle(); }
  s = await gameState();
  let rnPosts = s.posts.filter(p => p.platform === 'rednote');
  note(report.rednote, rnPosts.length > 0, 'real model generated RedNote posts from the current real card', { count: rnPosts.length });
  const rnButton = page.locator('#world-phone-stage [data-pg-post]').first();
  if (await rnButton.count()) {
    const id = await rnButton.getAttribute('data-pg-post');
    await rnButton.click(); await sleep(100);
    note(report.rednote, await page.locator('#world-phone-stage .echo-rn-detail').count() > 0, 'RedNote opens the independent detail DOM');
    note(report.rednote, await page.locator('#world-phone-stage .echo-rn-detail .echo-post').count() === 0, 'RedNote detail does not regress to generic postCard DOM');
    const like = page.locator(`#world-phone-stage [data-pg-like="${id}"]`).first(); if (await like.count()) await like.click();
    const save = page.locator(`#world-phone-stage [data-pg-save="${id}"]`).first(); if (await save.count()) await save.click();
    const ctext=`real-rn-comment-${Date.now()}`;
    const cform=page.locator('#world-phone-stage [data-pg-comment]').first();
    if(await cform.count()) { await cform.locator('[data-pg-draft]').fill(ctext); await cform.evaluate(el=>el.requestSubmit()); await waitGameIdle(); }
    s = await gameState();
    const p = s.posts.find(x=>x.id===id); const ce=s.events.find(e=>e.postId===id && e.text===ctext);
    note(report.rednote, Boolean(p?.liked), 'like state persisted on the same RedNote post');
    note(report.rednote, Boolean(ce), 'comment was written to the same RedNote post', { commentStatus:ce?.status });
    await page.locator('#world-phone-stage [data-pg-post-back]').click(); await sleep(100);
    await page.locator(`#world-phone-stage [data-pg-post="${id}"]`).click(); await sleep(100);
    s = await gameState();
    note(report.rednote, Boolean(s.posts.find(x=>x.id===id)?.liked), 'state remains after back and re-enter');
    await page.screenshot({ path:path.join(EVIDENCE,'03-rednote-real-detail.png') });
  }
  statusFrom(report.rednote);

  // P2 Weibo independent real generated posts and detail interaction.
  await openApp('weibo');
  const wbRefresh = page.locator('#world-phone-stage [data-pg-refresh="weibo"]').first();
  if (await wbRefresh.count()) { await wbRefresh.click(); await waitGameIdle(); }
  s = await gameState();
  const wbPosts = s.posts.filter(p=>p.platform==='weibo');
  note(report.weibo, wbPosts.length > 0, 'real model generated Weibo posts from the current real card', { count:wbPosts.length });
  const wbButton=page.locator('#world-phone-stage [data-pg-post]').first();
  if(await wbButton.count()) {
    const id=await wbButton.getAttribute('data-pg-post'); await wbButton.click(); await sleep(100);
    const rnDomLeak=await page.locator('#world-phone-stage .echo-rn-detail').count();
    note(report.weibo, rnDomLeak===0, 'Weibo detail does not use RedNote DOM');
    const like=page.locator(`#world-phone-stage [data-pg-like="${id}"]`).first(); if(await like.count()) await like.click();
    const text=`real-wb-comment-${Date.now()}`; const form=page.locator('#world-phone-stage [data-pg-comment]').first();
    if(await form.count()){await form.locator('[data-pg-draft]').fill(text); await form.evaluate(el=>el.requestSubmit()); await waitGameIdle();}
    s=await gameState();
    note(report.weibo, Boolean(s.posts.find(x=>x.id===id)?.liked), 'Weibo like persisted on the same post');
    note(report.weibo, Boolean(s.events.find(e=>e.postId===id&&e.text===text)), 'Weibo comment persisted on the same post');
    await page.locator('#world-phone-stage [data-pg-post-back]').click(); await sleep(80); await page.locator(`#world-phone-stage [data-pg-post="${id}"]`).click(); await sleep(80);
    note(report.weibo, await page.locator('#world-phone-stage .echo-rn-detail').count()===0, 'return/re-enter keeps Weibo DOM independent');
    await page.screenshot({path:path.join(EVIDENCE,'04-weibo-real-detail.png')});
  }
  s=await gameState();
  note(report.weibo, s.posts.filter(p=>p.platform==='weibo').every(p=>!s.posts.filter(r=>r.platform==='rednote').some(r=>r.id===p.id)), 'Weibo and RedNote post IDs remain separate in state');
  statusFrom(report.weibo);

  // P3 Delivery: normal purchase then inspect wallet/ledger/order/gift/reply. The game starts with its product-defined real balance, no test balance injection.
  await openApp('delivery');
  const beforeDelivery=await gameState();
  const merchant=page.locator('#world-phone-stage [data-pg-delivery-merchant="meal"]').first();
  if(await merchant.count()) await merchant.click(); await sleep(80);
  let add=page.locator('#world-phone-stage [data-pg-delivery-add="dinner"]').first();
  if(!await add.count()) add=page.locator('#world-phone-stage [data-pg-delivery-add]').first();
  const giftId=await add.getAttribute('data-pg-delivery-add');
  await add.click(); await sleep(80);
  const checkout=page.locator('#world-phone-stage [data-pg-delivery-go="checkout"]').first();
  note(report.delivery, await checkout.isEnabled().catch(()=>false), 'checkout enabled with a legal real recipient and sufficient product-defined balance', {balance:beforeDelivery.balance,giftId});
  if(await checkout.isEnabled().catch(()=>false)) {
    await checkout.click(); await sleep(80);
    await page.locator('#world-phone-stage [data-pg-delivery-address]').fill('实验酒馆前台');
    await page.locator('#world-phone-stage [data-pg-note]').fill('真实联调订单');
    const confirm=page.locator('#world-phone-stage [data-pg-delivery-confirm]').first();
    await confirm.dblclick({delay:20}).catch(async()=>{ if(await confirm.count()) await confirm.click(); });
    await waitGameIdle();
    const after=await gameState();
    const giftEvents=after.events.filter(e=>e.kind==='gift'&&e.giftId===giftId&&/真实联调订单/.test(e.note||''));
    const giftPrice=({coffee:25,cake:45,dinner:60,tea:20})[giftId] ?? Math.max(0,beforeDelivery.balance-after.balance);
    note(report.delivery, beforeDelivery.balance-after.balance===giftPrice, 'wallet deducted exactly once after a rapid double-click attempt', {before:beforeDelivery.balance,after:after.balance,price:giftPrice});
    note(report.delivery, giftEvents.length===1, 'rapid double-click produced exactly one gift/order event', {count:giftEvents.length});
    note(report.delivery, giftEvents[0]?.status==='replied' && Boolean(giftEvents[0]?.reply), 'delivery order reached the real host model reply for the correct recipient', {reply:giftEvents[0]?.reply?.slice(0,300)});
    note(report.delivery, after.ledger.some(x=>x.amount===-giftPrice && /送给/.test(x.text)), 'wallet ledger contains the matching deduction');
    const orderId=giftEvents[0]?.id;
    const orderText=await page.locator('#world-phone-stage .echo-delivery-order-card').innerText().catch(()=> '');
    note(report.delivery, Boolean(orderId)&&/已送达|等待回应/.test(orderText), 'order detail is available after checkout', {orderText:orderText.slice(0,500)});
    await page.screenshot({path:path.join(EVIDENCE,'05-delivery-real-order.png')});
  }
  statusFrom(report.delivery);

  // Lifecycle: queue a new real-thread action, immediately change mode, verify a late result does not mutate it.
  await openApp('wechat');
  const thread=page.locator('#world-phone-stage [data-pg-chat]').filter({hasText:/Seraphina/i}).first(); if(await thread.count()) await thread.click();
  const pendingText=`scope-cancel-${Date.now()}`;
  const form=page.locator('#world-phone-stage [data-pg-message]').first();
  if(await form.count()) {
    await form.locator('[data-pg-draft]').fill(pendingText); await form.evaluate(el=>el.requestSubmit());
    await sleep(20); await setMode('world'); await sleep(3500); await setMode('game');
    const stateAfterCancel=await gameState();
    const pending=stateAfterCancel.events.find(e=>e.text===pendingText);
    note(report.lifecycle, Boolean(pending), 'interaction stays saved when leaving game mode during an in-flight reply');
    note(report.lifecycle, pending?.status==='pending', 'stale in-flight reply was not written after world/game mode switch', {status:pending?.status, reply:pending?.reply||''});
  } else report.blockers.push('Lifecycle pending-request test could not find a real WeChat thread form.');
  statusFrom(report.lifecycle);

  // World Backstage bridge: only inspect/use data that the real chat produced. Do not inject phone surface data.
  await setMode('world');
  const world = await page.evaluate(() => {
    const host=globalThis.worldBackstageHost; const ctx=globalThis.SillyTavern?.getContext?.();
    const surface=host?.getPhoneSurface?.();
    return { hasHost:Boolean(host), version:host?.phoneBridgeVersion||0, capabilities:surface?.capabilities||[], connected:Boolean(surface?.connected), reason:surface?.reason||'', people:surface?.people?.map(x=>({id:x.id,name:x.name}))||[], conversations:surface?.social?.conversations?.length||0, moments:surface?.social?.moments?.length||0, notices:surface?.social?.notices?.length||0, chatId:ctx?.chatId||ctx?.getCurrentChatId?.()||'' };
  });
  report.bridge.surface=world;
  note(report.bridge, world.hasHost && world.version>=2, 'World Backstage formal phone bridge v2 host is present in the real runtime', {version:world.version});
  note(report.bridge, world.connected, 'World Backstage surface is connected to the current real chat', {reason:world.reason,chatId:world.chatId});
  note(report.bridge, Array.isArray(world.capabilities)&&world.capabilities.includes('social-send-message'), 'formal capabilities are exposed by the RC bridge', {capabilities:world.capabilities});
  if(!world.people.length && !world.conversations && !world.moments) {
    report.bridge.status='blocked'; report.blockers.push('World Backstage real chat did not produce social/SIM people/posts in this run; deeper world social actions are blocked by missing real generated world social data.');
  } else statusFrom(report.bridge);
  await page.screenshot({path:path.join(EVIDENCE,'06-world-mode-real-surface.png')});

  // 10-cycle responsiveness/listener smoke on actual rendered apps, no state injection.
  await setMode('game');
  const sequence=['wechat','weibo','rednote','delivery','wechat'];
  const timings=[];
  for(let round=0;round<10;round++) {
    const t0=Date.now();
    for(const app of sequence){await openApp(app); await sleep(30);}
    timings.push(Date.now()-t0);
  }
  report.performance.timingsMs=timings;
  const first=timings.slice(0,3).reduce((a,b)=>a+b,0)/3, last=timings.slice(-3).reduce((a,b)=>a+b,0)/3;
  note(report.performance, last <= first*2.2+250, '10-cycle navigation did not show runaway slowdown', {firstAvg:first,lastAvg:last,timings});
  const dom=await page.locator('#world-phone-stage *').count(); report.performance.domNodes=dom;
  note(report.performance, dom<5000, 'phone DOM did not grow without bound during 10 cycles', {domNodes:dom});
  statusFrom(report.performance);

  // Cross-app state isolation snapshot.
  s=await gameState();
  report.finalGameSnapshot={balance:s.balance,spent:s.spent,earned:s.earned,actors:s.actors.map(a=>({id:a.id,name:a.name})),postCounts:{rednote:s.posts.filter(p=>p.platform==='rednote').length,weibo:s.posts.filter(p=>p.platform==='weibo').length,moments:s.posts.filter(p=>p.platform==='moments').length},eventCount:s.events.length,ledgerCount:s.ledger.length,relations:Object.fromEntries(Object.entries(s.relations).map(([k,v])=>[k,{affinity:v.affinity,preferences:v.preferences,memory:v.memory?.slice(0,400),giftCounts:v.giftCounts}]))};
  await page.screenshot({path:path.join(EVIDENCE,'07-final-real-data-phone.png')});
} catch (error) {
  report.fatal = String(error?.stack || error);
} finally {
  fs.writeFileSync(path.join(EVIDENCE,'real-data-qa.json'), JSON.stringify(report,null,2));
  fs.writeFileSync(path.join(EVIDENCE,'real-data-qa.log'), JSON.stringify(report,null,2));
  await context.close(); await browser.close();
}

console.log(JSON.stringify(report,null,2));
if (report.fatal) process.exitCode=1;
